__rayModel.solve:
function solve() {
        const theta1 = Number(angleRange.value);
        const nMed = MEDIA[medium].n;
        const n1 = dir === 'in' ? N_AIR : nMed;
        const n2 = dir === 'in' ? nMed : N_AIR;
        const sinT2 = (n1 * Math.sin(rad(theta1))) / n2;
        const total = sinT2 > 1;                       // no real refracted ray
        const theta2 = total ? null : deg(Math.asin(sinT2));
        const critical = n1 > n2 ? deg(Math.asin(n2 / n1)) : null;
        return { theta1, theta2, reflect: theta1, n1, n2, total, critical };
    }

__soundModel.displacementAt:
function displacementAt(t) {
        if (strikeAt === null || t < strikeAt) return 0;
        const dt = t - strikeAt;
        const fd = ringHz / SLOWDOWN;
        return ringAmp * Math.exp(-dt / TAU) * Math.sin(2 * Math.PI * fd * dt);
    }

__soundModel.envelopeAt:
function envelopeAt(t) {
        if (strikeAt === null || t < strikeAt) return 0;
        return ringAmp * Math.exp(-(t - strikeAt) / TAU);
    }

__soundModel.ringDuration:
function ringDuration() {
        // How long until the ring is inaudible, plus the time for that tail
        // to scroll off the left edge of the scope.
        if (ringAmp <= CUTOFF) return 0;
        return TAU * Math.log(ringAmp / CUTOFF) + T_WIN;
    }

__waveModel.analyse:
function analyse(v = speed(), f = freq()) {
        const lambda = v / f;                          // v = f λ
        const period = 1 / f;
        const verdict = lambda > REF_LAMBDA + 0.05 ? 'longer'
            : lambda < REF_LAMBDA - 0.05 ? 'shorter' : 'same';
        return { v, f, lambda, period, verdict, lambdaPx: lambda * PX };
    }

__speedModel.analyse:
function analyse(s = state) {
        const A = MOVERS[s.a], B = MOVERS[s.b];
        const same = Math.abs(A.speed - B.speed) < 1e-9;
        const verdict = same ? 'same' : A.speed > B.speed ? 'a' : 'b';
        if (s.mode === 'distance') {
            const tA = COURSE_M / A.speed, tB = COURSE_M / B.speed;
            // the clock runs until the slower one arrives, but never past three minutes on screen
            const simEnd = Math.max(tA, tB);
            return { kind: 'distance', A, B, tA, tB, simEnd, verdict, same };
        }
        const dA = A.speed * CLOCK_S, dB = B.speed * CLOCK_S;
        return { kind: 'time', A, B, dA, dB, simEnd: CLOCK_S, trackM: Math.max(dA, dB) * 1.08, verdict, same };
    }

