__forceModel.analyse:
function analyse(F = push(), m = mass(), v0 = startSpeed(), key = floor) {
        const mu = FLOORS[key].mu;
        const weight = m * G;
        const fMax = mu * weight;                  // the most friction this floor can give
        const moving = v0 > 0;
        // Standing still, friction only pushes back as hard as it is pushed —
        // it never invents force of its own.
        const friction = moving ? fMax : Math.min(F, fMax);
        const net = F - friction;
        const accel = moving || F > fMax ? (F - fMax) / m : 0;
        let motion;
        if (!moving && F <= fMax) motion = 'rest';
        else if (accel > 1e-9) motion = 'faster';
        else if (accel < -1e-9) motion = 'slower';
        else motion = 'constant';

        // Where and when the run ends, in closed form: the acceleration is
        // constant, so there is nothing to integrate numerically.
        let endTime, stopTime = Infinity, reachedEnd = false;
        if (motion === 'rest') {
            endTime = REST_RUN;
        } else if (motion === 'slower') {
            stopTime = v0 / -accel;
            const stopDist = (v0 * v0) / (2 * -accel);
            if (stopDist >= TRACK_M) { endTime = timeToReach(TRACK_M, v0, accel); reachedEnd = true; }
            else endTime = stopTime;
        } else {
            endTime = timeToReach(TRACK_M, v0, accel);
            reachedEnd = true;
        }
        return { F, m, v0, mu, weight, fMax, friction, net, accel, motion, endTime, stopTime, reachedEnd, floorName: FLOORS[key].name };
    }

__forceModel.stateAt:
function stateAt(t, a = analyse()) {
        if (a.motion === 'rest') return { x: 0, v: 0 };
        const tm = Math.min(t, a.endTime, a.stopTime);
        const x = Math.min(TRACK_M, a.v0 * tm + 0.5 * a.accel * tm * tm);
        const v = Math.max(0, a.v0 + a.accel * tm);
        return { x, v };
    }

__forceModel.timeToReach:
function timeToReach(dist, v0, a) {
        if (Math.abs(a) < 1e-12) return v0 > 0 ? dist / v0 : Infinity;
        return (-v0 + Math.sqrt(v0 * v0 + 2 * a * dist)) / a;
    }

__forceModel.tick:
function tick(dt) {
        const a = analyse();
        simTime += dt;
        const limit = Number.isFinite(a.endTime) ? a.endTime : REST_RUN;
        let done = false;
        if (simTime >= limit) { simTime = limit; done = true; }
        render();
        return done;
    }

__motionModel.analyseIncline:
function analyseIncline(s = state) {
        const th = s.angle * Math.PI / 180;
        const a = G * Math.sin(th);
        const tRamp = Math.sqrt(2 * RAMP_M / a);
        const vEnd = a * tRamp;
        const tFlat = FLAT_M / vEnd;
        const total = tRamp + tFlat;
        // where the cart is (metres along the track) and how fast, at time t
        const at = t => {
            if (t <= tRamp) return { s: 0.5 * a * t * t, v: a * t, onRamp: true };
            return { s: RAMP_M + vEnd * (t - tRamp), v: vEnd, onRamp: false };
        };
        const flashes = [];
        for (let t = 0; t <= total + 1e-9; t += s.flash) flashes.push({ t, ...at(t) });
        return { kind: 'incline', th, a, tRamp, vEnd, tFlat, total, at, flashes, verdict: 'widen' };
    }

__motionModel.analyseEnergy:
function analyseEnergy(s = state) {
        const h0 = s.height, m = s.mass;
        const eTotal = m * G * h0;
        const x0 = startX(h0);
        // march the ball along the track; speed comes from energy alone
        const DT = 0.002, T_MAX = 6;
        const path = [];
        let x = x0, dir = 1, t = 0, peakX = x0, reached = false;
        for (let i = 0; t <= T_MAX; i += 1, t += DT) {
            const y = trackY(x);
            const v = Math.sqrt(Math.max(0, 2 * G * (h0 - y)));
            if (i % 10 === 0) path.push({ t, x, y, v });
            const slope = trackSlope(x);
            let dx = dir * (v * DT) / Math.sqrt(1 + slope * slope);
            // nudge off a turning point so the ball does not stick where v = 0
            if (v < 0.02) dx = dir * 0.0015;
            const nx = x + dx;
            if (trackY(nx) > h0 + 1e-9) { dir = -dir; continue; }
            x = nx;
            if (x > peakX) peakX = x;
            if (x >= END) { reached = true; path.push({ t, x: END, y: trackY(END), v }); break; }
            if (x <= 0) { dir = 1; x = 0; }
        }
        const passes = h0 > HILL2 + 1e-9;
        const verdict = passes ? 'pass' : Math.abs(h0 - HILL2) < 1e-9 ? 'stop' : 'back';
        const duration = path[path.length - 1].t;
        const vBottom = Math.sqrt(2 * G * h0);
        return { kind: 'energy', h0, m, eTotal, x0, path, passes, verdict, duration, vBottom, peakX, reached };
    }

__motionModel.trackY:
x => {
        if (x <= 2) return TOP * (1 + Math.cos(Math.PI * x / 2)) / 2;
        if (x <= 4) return HILL2 * (1 - Math.cos(Math.PI * (x - 2) / 2)) / 2;
        if (x <= 6) return 0.4 + (HILL2 - 0.4) * (1 + Math.cos(Math.PI * (x - 4) / 2)) / 2;
        return 0.4;
    }

__motionModel.sampleEnergy:
function sampleEnergy(a, p) {
        const t = p * a.duration;
        let lo = 0, hi = a.path.length - 1;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (a.path[mid].t < t) lo = mid + 1; else hi = mid; }
        const pt = a.path[Math.min(lo, a.path.length - 1)];
        const pe = a.m * G * pt.y, ke = Math.max(0, a.eTotal - pe);
        return { ...pt, pe, ke };
    }

