__weightModel.tick:
function tick(dt) {
    state.phase += dt;
    if (!state.running) return false;
    state.t = Math.min(1, state.t + dt / 5);
    if (state.t >= 1) {
        state.running = false;
        $('runBtn').textContent = '저울에 올리고 물에 넣기';
        state.checked = true;
        return true;
    }
    return false;
}

__buoyModel.buoyancy:
function buoyancy() {
        const rhoObj = mass() / vol();
        const rhoFl = FLUIDS[fluid].rho;
        // Three outcomes, not two. When the densities match exactly the body is
        // neutrally buoyant: fully submerged, yet held up entirely by buoyancy
        // with nothing left for the floor to push against, so it hovers rather
        // than resting on the bottom.
        const EPS = 1e-9;
        const state = rhoObj < rhoFl - EPS ? 'float'
                    : rhoObj > rhoFl + EPS ? 'sink' : 'neutral';
        const floats = state === 'float';
        const frac = floats ? rhoObj / rhoFl : 1;
        const vSub = vol() * frac;
        // ρ in g/cm³ is 1000 kg/m³ and V in cm³ is 1e-6 m³, so ρ·V·g in these
        // units comes out in newtons with a factor of 9.8e-3.
        const buoyN = rhoFl * vSub * G * 1e-3;
        const weightN = mass() * G * 1e-3;
        return { rhoObj, rhoFl, state, floats, frac, vSub, buoyN, weightN,
            normalN: state === 'sink' ? Math.max(0, weightN - buoyN) : 0 };
    }

__measureModel.analyse:
function analyse() {
        if (state.mode === 'scale') {
            const kind = KINDS[state.kind], t = TARGETS[state.kind][state.target];
            const lg = Math.log10(t.value / kind.ref), k = Math.abs(lg);
            return { kind: 'scale', k, t, lg, steps: Math.round(k), verdict: k < 4 ? 'near' : k < 8 ? 'mid' : 'far' };
        }
        if (state.mode === 'units') {
            const d = DEFS[state.unit][state.era];
            return { kind: 'units', d, verdict: d.cat };
        }
        const r = RULERS[state.ruler], reads = readingsFor(state.ruler);
        const mean = reads.reduce((s, v) => s + v, 0) / reads.length;
        const spread = (Math.max(...reads) - Math.min(...reads)) / 2;
        return { kind: 'measure', r, reads, mean, spread, verdict: state.ruler };
    }

__measureModel.readingsFor:
function readingsFor(rulerKey) {
        const r = RULERS[rulerKey];
        let seed = { cm: 11, mm: 23, vernier: 37 }[rulerKey];
        const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
        // eye error: within a fifth of a division either way, then rounded to the estimated digit
        return Array.from({ length: READS }, () => Number((TRUE_MM + (rnd() * 2 - 1) * r.div / 5).toFixed(decimals(r.est))));
    }

