__diffModel.meetPoint:
function meetPoint() {
        const rNH3 = 1 / Math.sqrt(NH3.M), rHCL = 1 / Math.sqrt(HCL.M);
        const fromNH3 = (TUBE_CM * rNH3) / (rNH3 + rHCL);
        return { fromNH3, fromHCL: TUBE_CM - fromNH3, ratio: rNH3 / rHCL };
    }

__diffModel.meetTime:
function meetTime(T) {
        const sum = speed(NH3.M, T) + speed(HCL.M, T);
        return TUBE_CM / sum;
    }

__diffModel.fronts:
function fronts(t, T) {
        const mp = meetPoint(), tm = meetTime(T);
        const capped = Math.min(t, tm);
        return {
            nh3: speed(NH3.M, T) * capped,
            hcl: speed(HCL.M, T) * capped,
            met: t >= tm, meetTime: tm, mp,
        };
    }

__diffModel.gasModel:
function gasModel() {
        const nCaCO3 = CACO3_G / CACO3_M;
        const nHCl = HCL_VOL_L * conc();
        const nFromAcid = nHCl / 2;
        const limiting = nFromAcid < nCaCO3 ? 'acid' : 'solid';
        const nCO2 = Math.min(nCaCO3, nFromAcid);
        const vMax = nCO2 * MOLAR_VOL_ML;
        const k = RATE_K * conc() * SURFACE[grain];
        return { nCaCO3, nHCl, nFromAcid, limiting, nCO2, vMax, k };
    }

__curveModel.solubility:
function solubility(key, t) {
        const d = SOLUTES[key].data;
        if (t <= TEMPS[0]) return d[0];
        if (t >= TEMPS[TEMPS.length - 1]) return d[d.length - 1];
        const i = Math.min(TEMPS.length - 2, Math.floor(t / 20));
        const span = TEMPS[i + 1] - TEMPS[i];
        return d[i] + ((d[i + 1] - d[i]) * (t - TEMPS[i])) / span;
    }

__curveModel.analyse:
function analyse() {
        const s1 = solubility(solute, temp());
        const max1 = (s1 * WATER_G) / 100;
        const dissolved = Math.min(added(), max1);
        const undissolved = added() - dissolved;
        const s2 = solubility(solute, coolTemp());
        const max2 = (s2 * WATER_G) / 100;
        // Raising the second temperature instead of lowering it means heating,
        // and then any solid still sitting on the bottom starts to dissolve.
        // Ignoring that would leave the picture wrong for half the slider.
        const heating = max2 > max1;
        const extraDissolved = heating ? Math.min(undissolved, max2 - dissolved) : 0;
        const dissolvedAfter = heating ? dissolved + extraDissolved : Math.min(dissolved, max2);
        const precipitated = heating ? 0 : dissolved - dissolvedAfter;
        const undissolvedAfter = undissolved - extraDissolved + precipitated;
        const saturated = added() >= max1 - 1e-9;
        return { s1, s2, max1, max2, dissolved, undissolved, dissolvedAfter,
            precipitated, extraDissolved, undissolvedAfter, heating, saturated };
    }

__crystalModel.solubility:
function solubility(T, key = salt) {
        const t = SALTS[key].table;
        if (T <= t[0][0]) return t[0][1];
        if (T >= t[t.length - 1][0]) return t[t.length - 1][1];
        for (let i = 1; i < t.length; i += 1) {
            if (T <= t[i][0]) {
                const [x0, y0] = t[i - 1], [x1, y1] = t[i];
                return y0 + ((y1 - y0) * (T - x0)) / (x1 - x0);
            }
        }
        return t[t.length - 1][1];
    }

__crystalModel.analyse:
function analyse(key = salt, w = water(), T1 = hot(), T2 = cold(), imp = dirt()) {
        const hi = Math.max(T1, T2), lo = Math.min(T1, T2);
        const s1 = solubility(hi, key), s2 = solubility(lo, key);
        const dissolved = (s1 * w) / 100;                 // a saturated solution at the hot end
        const canHold = (s2 * w) / 100;
        const crystals = Math.max(0, dissolved - canHold);
        // the impurity only comes out if it too passes its own saturation
        const impCanHold = (IMP_S * w) / 100;
        const impOut = Math.max(0, imp - impCanHold);
        const totalOut = crystals + impOut;
        const purity = totalOut > 1e-9 ? (crystals / totalOut) * 100 : 0;
        const verdict = impOut < 1e-9 ? 'pure' : purity >= 90 ? 'slight' : 'dirty';
        return { key, S: SALTS[key], w, T1: hi, T2: lo, s1, s2, dissolved, canHold,
                 crystals, imp, impCanHold, impOut, totalOut, purity, verdict };
    }

__crystalModel.outAt:
function outAt(T, a) {
        const held = (solubility(T, a.key) * a.w) / 100;
        const c = Math.max(0, Math.min(a.crystals, a.dissolved - held));
        const i = a.T2 >= T - 1e-9 ? a.impOut : 0;
        return { crystals: c, imp: i };
    }

__crystalModel.step:
function step(s, dt, a) {
        s.t += dt;
        const span = 3.2;                                  // seconds to cool all the way
        const f = Math.min(1, s.t / span);
        s.T = a.T1 + (a.T2 - a.T1) * f;
        if (f >= 1) s.done = true;
        return s.done;
    }

