        const frac = day - Math.floor(day), hh = Math.floor(frac * 24), mm = Math.floor((frac * 24 - hh) * 60);
        return `${m + 1}월 ${d + 1}일${withTime ? ` ${hh}시 ${String(mm).padStart(2, '0')}분` : ''}`;
    }

