function analyse() {
    const m = matchGrams(state.vin);
    const gas = gasLitres(state.vin, state.soda);
    const most = gasLitres(state.vin, 999);
    return {
        vin: state.vin, soda: state.soda, match: m, gas, most,
        leftSoda: Math.max(0, state.soda - m),
        leftVin: Math.max(0, (m - state.soda) / m) * state.vin,
        full: gas / most,
        verdict: verdictFor(state.vin, state.soda),
    };
}

__volcanoModel.tick:
function tick(dt) {
    state.phase += dt;
    if (!state.running) return false;
    state.t = Math.min(1, state.t + dt / 5);
    if (state.t >= 1) {
        state.running = false;
        $('runBtn').textContent = '소다 넣기';
        state.checked = true;
        return true;
    }
    return false;
}

__volcanoModel.verdictFor:
function verdictFor(ml, g) {
    const m = matchGrams(ml);
    if (Math.abs(g - m) <= NEAR) return 'p3';
    return g > m ? 'p1' : 'p2';
}

__plateModel.analyse:
function analyse(k = kind, v = speed(), t = years()) {
        const info = KINDS[k];
        const pts = quakes(k);
        const deepest = Math.max(...pts.map(p => p.depth));
        const dist = k === 'inside' ? moved(v, t) : moved(v, t);
        const total = k === 'inside' ? dist : dist * 2;   // both plates move
        const age = v > 0 ? dist / v * 1e5 / 1e4 : 0;     // ten-thousand-year units
        return { k, info, pts, deepest, dist, total, age, verdict: info.verdict, v, t };
    }

__plateModel.quakes:
function quakes(k = kind) {
        const r = rng({ diverge: 11, converge: 27, transform: 43, inside: 61 }[k]);
        const list = [];
        if (k === 'diverge') {
            for (let i = 0; i < 46; i += 1) list.push({ dist: (r() * 2 - 1) * 80, depth: r() * 15 });
        } else if (k === 'transform') {
            for (let i = 0; i < 46; i += 1) list.push({ dist: (r() * 2 - 1) * 50, depth: r() * 20 });
        } else if (k === 'inside') {
            for (let i = 0; i < 6; i += 1) list.push({ dist: (r() * 2 - 1) * 600, depth: r() * 25 });
        } else {
            // shallow ones right at the trench
            for (let i = 0; i < 16; i += 1) list.push({ dist: -30 + r() * 90, depth: r() * 45 });
            // then down the sinking slab: it dips at 45 degrees, so depth = distance
            for (let i = 0; i < 52; i += 1) {
                const s = r() * DEPTH_MAX;
                list.push({ dist: s + (r() * 2 - 1) * 34, depth: Math.max(4, s + (r() * 2 - 1) * 30) });
            }
        }
        return list;
    }

__earthModel.analyse:
function analyse() {
        if (state.mode === 'spheres') {
            const ph = PHENOMENA[state.phenomenon];
            return { kind: 'spheres', ph, verdict: ph.cat };
        }
        if (state.mode === 'water') {
            const r = RESERVOIRS[state.reservoir];
            return { kind: 'water', r, tau: tauOf(r), verdict: r.cat };
        }
        const em = EMITS[state.emit];
        const end = carbonAt(em.E, YEARS), change = end / C_NOW - 1;
        const sinkNow = K_SINK * (C_NOW - C_PRE);
        return { kind: 'carbon', em, end, change, sinkNow, verdict: change < -0.05 ? 'down' : change > 0.05 ? 'up' : 'same' };
    }

__earthModel.fmtTime:
years => {
        const days = years * 365;
        if (days < 60) return `${days < 10 ? days.toFixed(1) : Math.round(days)}일`;
        if (years < 2) return `${Math.round(years * 12)}개월`;
        if (years < 100) return `${Math.round(years)}년`;
        if (years < 1000) return `약 ${Math.round(years / 10) * 10}년`;
        return `약 ${fmtN(Math.round(years / 100) * 100)}년`;
    }

