function analyse() {
    const s = SKIES[state.sky];
    const w = windAt(state.hour);
    return {
        sky: s, hour: state.hour, land: landTemp(state.hour), sea: seaTemp(),
        wind: w, hi: tMax(state.sky), lo: tMin(state.sky), range: 2 * amp(state.sky),
        daylight: state.hour >= 6 && state.hour < 19,
        verdict: verdictFor(state.hour),
    };
}

__weatherModel.tick:
function tick(dt) {
    state.phase += dt;
    if (!state.running) return false;
    state.hour = state.hour + dt * 24 / 16;
    if (state.hour >= 24) {
        state.hour = 24;
        state.running = false;
        $('runBtn').textContent = '하루 지켜보기';
        state.checked = true;
    }
    $('timeRange').value = String(Math.round(state.hour * 2) / 2);
    $('timeOutput').textContent = koHour(state.hour);
    return !state.running;
}

__weatherModel.landTemp:
function landTemp(h, sky = state.sky) {
    const lo = tMin(sky), hi = tMax(sky), span = hi - lo;
    let t = ((h % 24) + 24) % 24;
    if (t >= T_MIN_H && t <= T_MAX_H) {
        return lo + span * (1 - Math.cos(Math.PI * (t - T_MIN_H) / (T_MAX_H - T_MIN_H))) / 2;
    }
    // the long fall from the afternoon peak round to the next sunrise
    if (t < T_MIN_H) t += 24;
    const fall = 24 - (T_MAX_H - T_MIN_H);
    return hi - span * (1 - Math.cos(Math.PI * (t - T_MAX_H) / fall)) / 2;
}

__weatherModel.windAt:
function windAt(h, sky = state.sky) {
    const d = landTemp(h, sky) - seaTemp();
    if (Math.abs(d) < CALM) return { dir: 'calm', speed: 0, diff: d };
    return { dir: d > 0 ? 'sea' : 'land', speed: Math.min(6, 0.6 * Math.abs(d)), diff: d };
}

__weatherModel.verdictFor:
function verdictFor(h, sky = state.sky) {
    const w = windAt(h, sky);
    return w.dir === 'sea' ? 'p1' : (w.dir === 'land' ? 'p2' : 'p3');
}

__weatherModel.analyseWind:
function analyseWind(spacing = state.spacing, system = state.system) {
        const gradient = (DP_HPA * 100) / (spacing * 1000);   // pascals per metre
        const v = gradient / (RHO * CORIOLIS);                 // metres per second
        const kmh = v * 3.6;
        const strength = v >= 20 ? 'strong' : v < 10 ? 'weak' : 'medium';
        return { kind: 'wind', spacing, system, gradient, v, kmh, strength, low: system === 'low' };
    }

__weatherModel.analyseFront:
function analyseFront(key = state.front) {
        const f = FRONTS[key];
        const rainHours = f.rainKm / f.speed;
        const rain = f.ahead ? [PASS_H - rainHours, PASS_H] : [PASS_H - 0.2, PASS_H - 0.2 + rainHours];
        const change = f.after - f.before;
        const verdict = change > 0.5 ? 'up' : change < -0.5 ? 'down' : 'same';
        return { kind: 'front', key, f, rainHours, rain, change, verdict };
    }

__weatherModel.tempAt:
function tempAt(h, a) {
        const f = a.f, half = f.shift / 2;
        if (h <= PASS_H - half) return f.before;
        if (h >= PASS_H + half) return f.after;
        return f.before + (f.after - f.before) * ((h - (PASS_H - half)) / f.shift);
    }

__weatherModel.windVector:
function windVector(theta, low) {
        // along the isobars, then tilted a little towards the low pressure
        const t = low ? [Math.sin(theta), -Math.cos(theta)] : [-Math.sin(theta), Math.cos(theta)];
        const radial = [Math.cos(theta), Math.sin(theta)];
        const sign = low ? -1 : 1;
        const x = t[0] * Math.cos(CROSS) + sign * radial[0] * Math.sin(CROSS);
        const y = t[1] * Math.cos(CROSS) + sign * radial[1] * Math.sin(CROSS);
        const n = Math.hypot(x, y);
        return [x / n, y / n];
    }

