__moonModel.phaseName:
function phaseName(E) {
        if (E < 22.5 || E >= 337.5) return '삭';
        if (E < 67.5) return '초승달';
        if (E < 112.5) return '상현달';
        if (E < 157.5) return '배부른 달';
        if (E < 202.5) return '보름달';
        if (E < 247.5) return '배부른 달';
        if (E < 292.5) return '하현달';
        return '그믐달';
    }

__moonModel.litPath:
function litPath(E, cx, cy, R) {
        const waxing = E <= 180;
        const Eprime = waxing ? E : 360 - E;
        const c = Math.cos(Eprime * Math.PI / 180);
        const side = waxing ? 1 : -1;
        const pts = [];
        for (let i = 0; i <= SAMPLES; i += 1) {           // limb, top to bottom
            const y = -R + (2 * R * i) / SAMPLES;
            pts.push([cx + side * Math.sqrt(Math.max(0, R * R - y * y)), cy + y]);
        }
        for (let i = SAMPLES; i >= 0; i -= 1) {           // terminator, back up
            const y = -R + (2 * R * i) / SAMPLES;
            pts.push([cx + side * c * Math.sqrt(Math.max(0, R * R - y * y)), cy + y]);
        }
        return `M${pts.map(p => `${p[0].toFixed(2)},${p[1].toFixed(2)}`).join('L')}Z`;
    }

__moonModel.sunlitHalfPath:
function sunlitHalfPath(r) {
        const pts = [];
        for (let i = 0; i <= SAMPLES; i += 1) {
            const a = (90 + (180 * i) / SAMPLES) * Math.PI / 180;
            pts.push([r * Math.cos(a), r * Math.sin(a)]);
        }
        return `M${pts.map(p => `${p[0].toFixed(2)},${p[1].toFixed(2)}`).join('L')}Z`;
    }

__skyModel.polar:
(aDeg, r) => ({
        x: POLARIS.x + r * Math.sin((aDeg * Math.PI) / 180),
        y: POLARIS.y - r * Math.cos((aDeg * Math.PI) / 180),
    })

__skyModel.clockLabel:
function clockLabel(h) {
        const t = (BASE_HOUR + h) % 24;
        const hh = Math.floor(t);
        const mm = Math.round((t - hh) * 60);
        const ampm = hh < 12 ? '오전' : '오후';
        const disp = hh % 12 === 0 ? 12 : hh % 12;
        return `${ampm} ${disp}시${mm ? ` ${mm}분` : ''}`;
    }

__starsModel.analyseBright:
function analyseBright(s = state) {
        const star = STARS[s.star];
        const d = BASE_PC * s.mult;
        const ratio = 1 / (s.mult * s.mult);
        const m0 = apparent(star.abs, BASE_PC), m1 = apparent(star.abs, d);
        return { kind: 'bright', star, d, ratio, m0, m1, dm: m1 - m0, verdict: 'square' };
    }

__starsModel.analyseExpand:
function analyseExpand(s = state) {
        const S = s.stretch;
        const rows = GALAXIES.map((name, i) => {
            const d0 = Math.abs(i - s.home);
            return { name, i, d0, d1: d0 * S, moved: d0 * (S - 1), speed: d0 * (S - 1) / RUN_SECONDS };
        });
        return { kind: 'expand', S, home: s.home, rows, verdict: 'faster' };
    }

__starsModel.brightAt:
(p, a) => {
        const d = BASE_PC + (a.d - BASE_PC) * p;
        const n = d / BASE_PC;
        return { d, n, ratio: 1 / (n * n), m: apparent(a.star.abs, d) };
    }

